"""Generate docs/DATA_MODEL.md by introspecting the SQLAlchemy metadata (db/models.py)."""
import os
import sys
import tempfile
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
os.environ.setdefault("CAREERPILOT_DATA_DIR", tempfile.mkdtemp(prefix="cp_gen_"))
sys.path.insert(0, str(ROOT / "services" / "api" / "src"))

from careerpilot.db import Base  # noqa: E402
from careerpilot.db import models  # noqa: E402,F401


def main() -> int:
    out = ["# Data model", "",
           "Generated by `python scripts/gen_data_model.py` from `db/models.py`. Do not edit by hand.",
           "Most tables inherit `Entity` (`id`, `workspace_id`, `created_at`, `updated_at`, "
           "`deleted_at` soft delete).", "",
           f"{len(Base.metadata.tables)} tables.", ""]
    for name in sorted(Base.metadata.tables):
        t = Base.metadata.tables[name]
        out += [f"## `{name}`", "", "| Column | Type | Null | Key / FK |", "|---|---|---|---|"]
        for c in t.columns:
            keys = []
            if c.primary_key:
                keys.append("PK")
            keys += [f"-> {fk.target_fullname}" for fk in c.foreign_keys]
            if c.index:
                keys.append("idx")
            out.append(f"| {c.name} | {str(c.type)} | {'yes' if c.nullable else 'no'} | "
                       f"{', '.join(keys)} |")
        extra = [str(x.name or x) for x in t.constraints
                 if x.__class__.__name__ in ("UniqueConstraint", "CheckConstraint")]
        if extra:
            out += ["", "Constraints: " + ", ".join(f"`{e}`" for e in extra)]
        out.append("")
    (ROOT / "docs" / "DATA_MODEL.md").write_text("\n".join(out), encoding="utf-8")
    print(f"wrote docs/DATA_MODEL.md ({len(Base.metadata.tables)} tables)")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
